import re
import os
import subprocess

def task_func(dir_path, exe_pattern, execute_files=True):
    pattern = re.compile(exe_pattern)
    results = []

    for entry in sorted(os.scandir(dir_path), key=lambda item: item.name):
        if not entry.is_file():
            continue
        if not os.access(entry.path, os.X_OK):
            continue
        if not pattern.search(entry.name):
            continue

        if execute_files:
            completed = subprocess.run(
                [entry.path],
                stdout=subprocess.PIPE,
                text=True,
                check=False,
            )
            results.append(completed.stdout)
        else:
            results.append(entry.path)

    return results

