import numpy as np
from scipy.stats import norm


def task_func(data: np.ndarray, threshold: float = 2.0) -> list:
    mean, standard_deviation = norm.fit(data)
    variance = standard_deviation**2

    if standard_deviation == 0:
        return [], float(mean), float(variance)

    z_scores = np.abs((data - mean) / standard_deviation)
    outliers = np.where(z_scores > threshold)[0].tolist()

    return outliers, float(mean), float(variance)

