import json
import csv
import os
import base64


def task_func(raw_string, filename, output_dir):
    decoded = base64.b64decode(raw_string).decode("utf-8")
    data = json.loads(decoded)

    os.makedirs(output_dir, exist_ok=True)
    file_path = os.path.join(output_dir, filename)

    def csv_value(value):
        if isinstance(value, (dict, list)):
            return json.dumps(value, ensure_ascii=False)
        return value

    with open(file_path, "w", newline="", encoding="utf-8") as csv_file:
        writer = csv.writer(csv_file)

        if isinstance(data, list):
            if data and all(isinstance(item, dict) for item in data):
                headers = list(dict.fromkeys(
                    key for item in data for key in item.keys()
                ))
                writer.writerow(headers)
                for item in data:
                    writer.writerow([csv_value(item.get(header, "")) for header in headers])
            elif data:
                for item in data:
                    writer.writerow([csv_value(item)])
        elif isinstance(data, dict):
            writer.writerow(list(data.keys()))
            writer.writerow([csv_value(value) for value in data.values()])
        else:
            writer.writerow([csv_value(data)])

    return file_path

