import pandas as pd
import re
import random

def task_func(s: str, seed: int = 0) -> pd.DataFrame:
    columns = ["ID", "Quantity", "Code", "Price", "Product", "Description"]
    product_names = ["Apple", "Banana", "Orange", "Pear", "Grape"]
    rng = random.Random(seed)
    code_to_product = {}
    records = []

    for line_number, line in enumerate(s.splitlines(), start=1):
        if not line.strip():
            continue

        parts = re.split(r"\s+", line.strip(), maxsplit=4)
        if len(parts) != 5:
            raise ValueError(
                f"Line {line_number} must contain ID, quantity, code, price, "
                "and description."
            )

        item_id, quantity, code, price, description = (
            part.strip() for part in parts
        )

        try:
            quantity = int(quantity)
            price = int(price)
        except ValueError as exc:
            raise ValueError(
                f"Line {line_number} contains a non-integer quantity or price."
            ) from exc

        if code not in code_to_product:
            code_to_product[code] = rng.choice(product_names)

        records.append(
            {
                "ID": item_id,
                "Quantity": quantity,
                "Code": code,
                "Price": price,
                "Product": code_to_product[code],
                "Description": description,
            }
        )

    return pd.DataFrame(records, columns=columns)

