import os
import shutil

# Constants
BACKUP_DIR = '/tmp/backup'


def get_unique_backup_dir():
    return "/fake/backup/path"


def task_func(directory):
    backup_directory = get_unique_backup_dir()
    errors = []

    if not os.path.isdir(directory):
        errors.append(FileNotFoundError(f"Directory does not exist: {directory}"))
        return backup_directory, errors

    try:
        os.makedirs(backup_directory, exist_ok=True)
    except OSError as error:
        return backup_directory, [error]

    try:
        entries = list(os.scandir(directory))
    except OSError as error:
        return backup_directory, [error]

    for entry in entries:
        destination = os.path.join(backup_directory, entry.name)

        try:
            if entry.is_dir(follow_symlinks=False):
                shutil.copytree(entry.path, destination)
            else:
                shutil.copy2(entry.path, destination)
        except (OSError, shutil.Error) as error:
            errors.append(error)
            continue

        try:
            if entry.is_dir(follow_symlinks=False):
                shutil.rmtree(entry.path)
            else:
                os.unlink(entry.path)
        except OSError as error:
            errors.append(error)

    return backup_directory, errors

