import random
import string
import pandas as pd


def task_func(data_list, seed=0):
    rng = random.Random(seed)
    modified_strings = []

    for value in data_list:
        candidates = []
        start = 0

        for index, char in enumerate(value + ","):
            if char == ",":
                if start < index:
                    candidates.append((start, index))
                start = index + 1

        if candidates:
            left, right = rng.choice(candidates)
            replacement = "".join(
                rng.choice(string.ascii_lowercase)
                for _ in range(right - left)
            )
            modified = value[:left] + replacement + value[right:]
        else:
            modified = value

        modified_strings.append(modified)

    return pd.DataFrame(
        {
            "Original String": data_list,
            "Modified String": modified_strings,
        }
    )

