import pandas as pd

try:
    from sklearn.feature_selection import f_oneway
except ImportError:
    from scipy.stats import f_oneway

def task_func(data_file_path: str):
    import matplotlib.pyplot as plt
    from itertools import combinations

    data = pd.read_csv(data_file_path)

    for column in data.columns:
        if data[column].dtype == "object":
            data[column] = data[column].str.replace(",", "", regex=False)
        data[column] = pd.to_numeric(data[column], errors="coerce")

    means = data.mean()
    std_devs = data.std()

    axes = []
    for column in data.columns:
        _, ax = plt.subplots()
        data[column].dropna().hist(ax=ax)
        ax.set_title(f"Histogram of {column}")
        ax.set_xlabel(column)
        ax.set_ylabel("Frequency")
        axes.append(ax)

    result_columns = ["Column 1", "Column 2", "F-value", "P-value"]
    anova_rows = []

    if len(data.columns) >= 2:
        for column_1, column_2 in combinations(data.columns, 2):
            values_1 = data[column_1].dropna()
            values_2 = data[column_2].dropna()

            if len(values_1) == 0 or len(values_2) == 0:
                f_value, p_value = float("nan"), float("nan")
            else:
                f_value, p_value = f_oneway(values_1, values_2)

            anova_rows.append(
                {
                    "Column 1": column_1,
                    "Column 2": column_2,
                    "F-value": f_value,
                    "P-value": p_value,
                }
            )

    anova_results = pd.DataFrame(anova_rows, columns=result_columns)

    return means, std_devs, axes, anova_results

