                if row and row[0] == target_value:
                    result[entry.name] = row_index
                    break

        if not simulate:
            destination = os.path.join(processed_dir, entry.name)
            if os.path.abspath(entry.path) != os.path.abspath(destination):
                shutil.move(entry.path, destination)

    return result

