import csv
from difflib import ndiff


def task_func(file_path1, file_path2, delimiter=',', quotechar='"'):
    def read_lines(file_path):
        try:
            with open(file_path, 'r', encoding='utf-8', newline='') as file:
                content = file.read()
        except FileNotFoundError:
            raise
        except Exception as exc:
            raise Exception(f"Unable to read file: {file_path}") from exc

        if content == '':
            raise ValueError(f"File is empty: {file_path}")

        # Validate CSV configuration while preserving the original line text.
        list(csv.reader(content.splitlines(), delimiter=delimiter, quotechar=quotechar))
        return content.splitlines()

    lines1 = read_lines(file_path1)
    lines2 = read_lines(file_path2)

    differences = []
    line1_number = 0
    line2_number = 0

    for diff_line in ndiff(lines1, lines2):
        status = diff_line[0]

        if status == '?':
            continue

        content = diff_line[2:]

        if status == ' ':
            line1_number += 1
            line2_number += 1
            line_number = line1_number
        elif status == '-':
            line1_number += 1
            line_number = line1_number
        else:
            line2_number += 1
            line_number = line2_number

        differences.append({
            'Line Number': line_number,
            'Status': status,
            'Content': content
        })

    return pd.DataFrame(
        differences,
        columns=['Line Number', 'Status', 'Content']
    )

