import numpy as np
from scipy import stats
import matplotlib.pyplot as plt

TARGET_VALUES = np.array([1, 3, 4])


def task_func(df):
    transformed_df = df.copy()

    for column in transformed_df.columns:
        values = transformed_df[column].where(
            transformed_df[column].isin(TARGET_VALUES), 0
        ).to_numpy(dtype=float)

        if values.size == 0:
            transformed_df[column] = values
            continue

        if np.all(values == values[0]):
            if values[0] > 0:
                try:
                    values = stats.boxcox(values)
                except ValueError:
                    values = np.full_like(values, values[0], dtype=float)
            else:
                values = np.zeros_like(values, dtype=float)
        else:
            values = stats.boxcox(values + 1)

        transformed_df[column] = values

    n_columns = len(transformed_df.columns)
    fig, axes = plt.subplots(
        nrows=max(n_columns, 1),
        ncols=1,
        figsize=(8, max(4, 3 * n_columns)),
        squeeze=False,
    )
    axes = axes.ravel()

    for index, column in enumerate(transformed_df.columns):
        ax = axes[index]
        values = transformed_df[column].dropna().to_numpy(dtype=float)

        if values.size > 1 and np.unique(values).size > 1:
            kde = stats.gaussian_kde(values)
            grid = np.linspace(values.min(), values.max(), 200)
            ax.plot(grid, kde(grid), label=column)
        elif values.size:
            ax.axvline(values[0], label=column)

        ax.set_title(f"KDE of {column}")
        ax.set_xlabel("Transformed value")
        ax.set_ylabel("Density")
        ax.legend()

    if n_columns == 0:
        axes[0].set_visible(False)

    fig.tight_layout()
    plt.show()

    return transformed_df, fig

