    if sample_size > 0 and len(matches) == 0:
        raise ValueError("Cannot sample from an empty set of matching rows.")

    random.seed(seed)
    indices = [
        random.randint(0, len(matches) - 1)
        for _ in range(sample_size)
    ]

    return matches.iloc[indices]

