import pandas as pd
import itertools
import random

def task_func(colors, states):
    colors = list(colors)
    states = list(states)
    num_columns = min(len(colors), len(states))

    if num_columns == 0:
        return pd.DataFrame()

    combinations = [
        f"{color}:{state}"
        for color, state in itertools.product(colors, states)
    ]
    random.shuffle(combinations)

    base_size, remainder = divmod(len(combinations), num_columns)
    columns = []
    start = 0

    for index in range(num_columns):
        size = base_size + (1 if index < remainder else 0)
        columns.append(combinations[start:start + size])
        start += size

    return pd.DataFrame({
        f"Column_{index + 1}": values
        for index, values in enumerate(columns)
    })

