import re
import json
import requests


def task_func(data_url: str) -> list:
    try:
        response = requests.get(data_url)
        content = response.text
        json.loads(content)

        bracket_depth = 0
        depths = [0] * len(content)
        in_string = False
        escaped = False

        for index, char in enumerate(content):
            depths[index] = bracket_depth

            if in_string:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == '"':
                    in_string = False
            elif char == '"':
                in_string = True
            elif char == "[":
                bracket_depth += 1
            elif char == "]":
                bracket_depth = max(0, bracket_depth - 1)

        pattern = re.compile(
            r'"name"\s*:\s*("(?:\\.|[^"\\])*")'
        )

        names = []
        for match in pattern.finditer(content):
            if depths[match.start()] == 0:
                names.append(json.loads(match.group(1)))

        return names
    except Exception:
        return "Invalid url input"

