import numpy as np
import pandas as pd
import numbers


def task_func(
    products,
    n_samples=100,
    sales_lower=50,
    sales_upper=200,
    profit_margin_min=0.1,
    profit_margin_max=0.5,
    random_seed=42,
):
    if not isinstance(products, list) or not all(
        isinstance(product, str) for product in products
    ):
        raise TypeError("products must be a list of strings")

    if not isinstance(n_samples, numbers.Integral) or isinstance(n_samples, bool):
        raise ValueError("n_samples must be a positive integer")
    if n_samples <= 0:
        raise ValueError("n_samples must be a positive integer")

    numeric_values = (
        sales_lower,
        sales_upper,
        profit_margin_min,
        profit_margin_max,
    )
    if not all(
        isinstance(value, numbers.Real) and not isinstance(value, bool)
        for value in numeric_values
    ):
        raise TypeError("sales and profit margin bounds must be numeric")

    if sales_lower > sales_upper:
        raise ValueError("sales_lower must not be greater than sales_upper")

    columns = ["Product", "Total Sales", "Total Profit"]
    if not products:
        return pd.DataFrame(columns=columns)

    rng = np.random.RandomState(random_seed)

    if (
        float(sales_lower).is_integer()
        and float(sales_upper).is_integer()
    ):
        sales = rng.randint(
            int(sales_lower), int(sales_upper) + 1, size=int(n_samples)
        )
    else:
        sales = rng.uniform(
            sales_lower, sales_upper, size=int(n_samples)
        )

    margins = rng.uniform(
        profit_margin_min, profit_margin_max, size=int(n_samples)
    )
    selected_products = rng.choice(products, size=int(n_samples))

    data = pd.DataFrame(
        {
            "Product": selected_products,
            "Sales": sales,
            "Profit": sales * margins,
        }
    )

    report = (
        data.groupby("Product", as_index=False)
        .agg(Total_Sales=("Sales", "sum"), Total_Profit=("Profit", "sum"))
    )

    product_order = list(dict.fromkeys(products))
    report = (
        report.set_index("Product")
        .reindex(product_order, fill_value=0)
        .reset_index()
    )

    return report.sort_values(
        by="Total Profit" if "Total Profit" in report.columns else "Total_Profit",
        ascending=False,
        ignore_index=True,
    ).rename(columns={"Total_Profit": "Total Profit"})

