import bs4
import requests
import re
import json


def task_func(url: str, output_path: str) -> list:
    from pathlib import Path
    from urllib.parse import urlparse, unquote

    parsed = urlparse(url)

    if parsed.scheme in ("http", "https"):
        response = requests.get(url)
        response.raise_for_status()
        content = response.text
    else:
        if parsed.scheme == "file":
            file_path = unquote(parsed.path)
            if parsed.netloc:
                file_path = f"//{parsed.netloc}{file_path}"
        else:
            file_path = url

        content = Path(file_path).read_text(encoding="utf-8", errors="ignore")

    soup = bs4.BeautifulSoup(content, "html.parser")
    text = soup.get_text(" ", strip=True)

    tel_links = [
        link.get("href", "")
        for link in soup.find_all("a", href=True)
        if link.get("href", "").lower().startswith("tel:")
    ]
    searchable_text = f"{text} {' '.join(tel_links)}"

    pattern = re.compile(r"(?<!\w)\+?\d[\d\s().-]{5,}\d(?!\w)")
    phone_numbers = []

    for match in pattern.findall(searchable_text):
        number = match.strip(" .-")
        digit_count = len(re.sub(r"\D", "", number))

        if not 7 <= digit_count <= 15:
            continue

        if re.fullmatch(r"\+?\d{1,4}([./-]\d{1,4}){1,3}", number):
            continue

        if number not in phone_numbers:
            phone_numbers.append(number)

    with open(output_path, "w", encoding="utf-8") as output_file:
        json.dump(phone_numbers, output_file, ensure_ascii=False, indent=2)

    return phone_numbers

