from itertools import combinations
import math
def task_func(seq, letter_weight_dict):
    if not seq:
        return ""

    weights = [letter_weight_dict[char] for char in seq]
    positive_subsequence = "".join(
        char for char, weight in zip(seq, weights) if weight > 0
    )

    if positive_subsequence:
        return positive_subsequence

    max_weight = -math.inf
    best_char = ""

    for char, weight in zip(seq, weights):
        if weight > max_weight:
            max_weight = weight
            best_char = char

    return best_char

