            or not math.isfinite(population)
            or population < 0
        ):
            raise ValueError("Populations must be non-negative numbers")

        rows.append(
            {
                "Country": country,
                "Population": math.floor(population)
                if isinstance(population, float)
                else population,
            }
        )

    dataframe = pd.DataFrame(rows, columns=["Country", "Population"])
