from collections import Counter
from sklearn.cluster import KMeans
import matplotlib.pyplot as plt


def task_func(df, n_clusters=3, random_state=None, n_init=10):
    """Identify duplicate points, cluster unique points, and plot the clusters."""
    if not hasattr(df, "drop_duplicates") or not hasattr(df, "itertuples"):
        raise TypeError("df must be a pandas DataFrame")

    if df.shape[1] == 0:
        raise ValueError("df must contain at least one feature column")

    if not isinstance(n_clusters, int) or isinstance(n_clusters, bool) or n_clusters < 1:
        raise ValueError("n_clusters must be a positive integer")

    point_counts = Counter(df.itertuples(index=False, name=None))
    duplicate_counts = Counter(
        {point: count for point, count in point_counts.items() if count > 1}
    )

    unique_df = df.drop_duplicates().copy()

    if unique_df.empty:
        raise ValueError("df must contain at least one point")

    if n_clusters > len(unique_df):
        raise ValueError(
            "n_clusters cannot exceed the number of unique points"
        )

    try:
        model = KMeans(
            n_clusters=n_clusters,
            random_state=random_state,
            n_init=n_init,
        )
        labels = model.fit_predict(unique_df.to_numpy())
    except (TypeError, ValueError) as exc:
        raise ValueError("df must contain numeric feature columns") from exc

    unique_df["cluster"] = labels

    _, ax = plt.subplots()
    if unique_df.shape[1] - 1 == 1:
        ax.scatter(
            unique_df.iloc[:, 0],
            [0] * len(unique_df),
            c=labels,
            cmap="viridis",
        )
        ax.set_ylabel(" ")
    else:
        ax.scatter(
            unique_df.iloc[:, 0],
            unique_df.iloc[:, 1],
            c=labels,
            cmap="viridis",
        )
        ax.set_ylabel(str(unique_df.columns[1]))

    ax.set_xlabel(str(unique_df.columns[0]))
    ax.set_title("KMeans Clustering of Unique Points")

    return duplicate_counts, unique_df, ax

