import random
import string


def task_func(length: int, predicates: list, seed: int = None):
    if length < 0:
        raise ValueError("length must be non-negative")

    def has_uppercase(text):
        return any(char.isupper() for char in text)

    def has_lowercase(text):
        return any(char.islower() for char in text)

    def has_digit(text):
        return any(char.isdigit() for char in text)

    def has_punctuation(text):
        return any(char in string.punctuation for char in text)

    def has_letter(text):
        return any(char.isalpha() for char in text)

    def has_whitespace(text):
        return any(char.isspace() for char in text)

    predicate_map = {
        "isalpha": str.isalpha,
        "isdigit": str.isdigit,
        "isalnum": str.isalnum,
        "islower": str.islower,
        "isupper": str.isupper,
        "istitle": str.istitle,
        "isspace": str.isspace,
        "isprintable": str.isprintable,
        "isascii": str.isascii,
        "isdecimal": str.isdecimal,
        "isnumeric": str.isnumeric,
        "isidentifier": str.isidentifier,
        "contains_uppercase": has_uppercase,
        "has_uppercase": has_uppercase,
        "contains_lowercase": has_lowercase,
        "has_lowercase": has_lowercase,
        "contains_digit": has_digit,
        "has_digit": has_digit,
        "contains_punctuation": has_punctuation,
        "has_punctuation": has_punctuation,
        "contains_special": has_punctuation,
        "has_special": has_punctuation,
        "contains_letter": has_letter,
        "has_letter": has_letter,
        "contains_whitespace": has_whitespace,
        "has_whitespace": has_whitespace,
    }

    unique_predicates = list(dict.fromkeys(predicates))

    for predicate in unique_predicates:
        try:
            if predicate not in predicate_map:
                raise KeyError(predicate)
        except TypeError:
            raise KeyError(predicate)

    if seed is not None:
        random.seed(seed)

    alphabet = string.ascii_letters + string.digits + string.punctuation
    text = "".join(random.choice(alphabet) for _ in range(length))

    characteristics = {
        predicate: predicate_map[predicate](text)
        for predicate in unique_predicates
    }

    return text, characteristics

