import random
import re

def task_func(text, seed=None):
    rng = random.Random(seed)

    def scramble(match):
        word = match.group(0)
        if len(word) <= 3:
            return word

        middle = list(word[1:-1])
        rng.shuffle(middle)
        return word[0] + "".join(middle) + word[-1]

    return re.sub(r"\b\w+\b", scramble, text)

