import requests
import json
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt

# Constants
HEADERS = {
    'accept': 'application/json'
}


def task_func(url, parameters):
    """
    Retrieve JSON data, convert it to a DataFrame, and display a correlation heatmap.

    Returns:
        tuple: A tuple containing the DataFrame and the heatmap Axes object.

    Raises:
        Exception: If the URL is invalid, inaccessible, the response is invalid,
                   or the response contains no usable data.
    """
    try:
        if not isinstance(url, str) or not url.strip():
            raise ValueError("The URL must be a non-empty string.")

        response = requests.get(
            url,
            params=parameters,
            headers=HEADERS,
            timeout=10
        )
        response.raise_for_status()

        try:
            payload = response.json()
        except (ValueError, json.JSONDecodeError) as exc:
            raise ValueError("The response is not valid JSON.") from exc

        if payload is None or payload == "":
            raise ValueError("The response contains no data.")

        if isinstance(payload, dict):
            for key in ("data", "results", "items", "records"):
                if key in payload:
                    payload = payload[key]
                    break

        if isinstance(payload, list):
            if not payload:
                raise ValueError("The response contains empty data.")
            dataframe = pd.DataFrame(payload)
        elif isinstance(payload, dict):
            dataframe = pd.DataFrame([payload])
        else:
            raise ValueError("The response has an unsupported data format.")

        if dataframe.empty:
            raise ValueError("The resulting DataFrame is empty.")

        numerical_data = dataframe.select_dtypes(include="number")
        if numerical_data.shape[1] < 2:
            raise ValueError(
                "The data must contain at least two numerical characteristics."
            )

        correlation = numerical_data.corr()
        if correlation.empty:
            raise ValueError("Unable to calculate correlations.")

        axes = sns.heatmap(
            correlation,
            annot=True,
            cmap="coolwarm",
            center=0
        )
        plt.show()

        return dataframe, axes

    except Exception as exc:
        raise Exception(f"Unable to retrieve or process the data: {exc}") from exc

