import os
import glob
from collections import Counter

def task_func(directory, extensions=[".txt", ".docx", ".xlsx", ".csv"], keep_zero=True):
    if not os.path.isdir(directory):
        raise OSError(f"Directory does not exist: {directory}")

    extensions = list(extensions)
    counts = Counter({extension: 0 for extension in extensions})
    extension_set = set(extensions)

    for path in glob.iglob(os.path.join(directory, "**", "*"), recursive=True):
        if os.path.isfile(path):
            extension = os.path.splitext(path)[1]
            if extension in extension_set:
                counts[extension] += 1

    if not keep_zero:
        counts = Counter(
            extension for extension, count in counts.items() if count > 0
        )

    return counts

