import pandas as pd
import numpy as np
from random import choice

# Constants
DATA_TYPES = [str, int, float, list, tuple, dict, set]


def task_func(rows, columns):
    if not isinstance(rows, int) or not isinstance(columns, int):
        raise TypeError("rows and columns must be integers")
    if rows < 0 or columns < 0:
        raise ValueError("rows and columns must be non-negative")

    def generate_value(data_type):
        if data_type is str:
            letters = np.random.choice(list("abcdefghijklmnopqrstuvwxyz"), size=5)
            return "".join(letters)

        if data_type is int:
            return int(np.random.randint(0, 10))

        if data_type is float:
            return float(np.random.randint(0, 10))

        size = int(np.random.randint(1, 6))

        if data_type is list:
            return [int(value) for value in np.random.randint(0, 10, size=size)]

        if data_type is tuple:
            return tuple(int(value) for value in np.random.randint(0, 10, size=size))

        if data_type is dict:
            keys = np.random.choice(np.arange(10), size=size, replace=False)
            values = np.random.randint(0, 10, size=size)
            return {int(key): int(value) for key, value in zip(keys, values)}

        if data_type is set:
            values = np.random.choice(np.arange(10), size=size, replace=False)
            return {int(value) for value in values}

        raise ValueError(f"Unsupported data type: {data_type}")

    data = {
        f"col{column}": [
            generate_value(choice(DATA_TYPES)) for _ in range(rows)
        ]
        for column in range(columns)
    }

    return pd.DataFrame(data, columns=[f"col{column}" for column in range(columns)])

