import pandas as pd
import re

# Function to replace acronyms in DataFrame
def task_func(data, mapping):
    result = data.copy()

    if not mapping:
        return result

    acronyms = sorted(
        (key for key in mapping if isinstance(key, str)),
        key=len,
        reverse=True,
    )

    if not acronyms:
        return result

    pattern = re.compile(
        r"(?<!\w)(?:"
        + "|".join(re.escape(acronym) for acronym in acronyms)
        + r")(?!\w)"
    )

    def replace_acronyms(value):
        if not isinstance(value, str):
            return value

        return pattern.sub(lambda match: mapping[match.group(0)], value)

    for column in result.columns:
        result[column] = result[column].map(replace_acronyms)

    return result

