import re
from datetime import time
def task_func(logs: list):
    error_times = []
    time_pattern = re.compile(
        r"(?<!\d)(?P<hour>[01]\d|2[0-3]):"
        r"(?P<minute>[0-5]\d)"
        r"(?::(?P<second>[0-5]\d)(?:\.(?P<fraction>\d{1,6}))?)?"
        r"(?!\d)"
    )

    for log in logs:
        if not re.search(r"\berror\b", str(log), re.IGNORECASE):
            continue

        match = time_pattern.search(str(log))
        if not match:
            continue

        fraction = (match.group("fraction") or "").ljust(6, "0")
        error_times.append(
            time(
                int(match.group("hour")),
                int(match.group("minute")),
                int(match.group("second") or 0),
                int(fraction or 0),
            )
        )

    if not error_times:
        return {"list": [], "time": None}

    total_microseconds = sum(
        (
            item.hour * 3600 + item.minute * 60 + item.second
        ) * 1_000_000 + item.microsecond
        for item in error_times
    )
    average_microseconds = round(total_microseconds / len(error_times))

    seconds, microseconds = divmod(average_microseconds, 1_000_000)
    seconds %= 24 * 3600
    hours, remainder = divmod(seconds, 3600)
    minutes, seconds = divmod(remainder, 60)

    return {
        "list": error_times,
        "time": time(hours, minutes, seconds, microseconds),
    }

