from random import choice, seed


def task_func(
    n_colors,
    colors=['Red', 'Green', 'Blue', 'Yellow', 'Purple'],
    rng_seed=None,
):
    if n_colors <= 0:
        return []

    if rng_seed is not None:
        seed(rng_seed)

    color_cycle = cycle(colors)
    pattern = []

    for index in range(n_colors):
        if index % 2 == 0:
            pattern.append(next(color_cycle))
        else:
            pattern.append(choice(colors))

    return pattern

