import csv
import re
from collections import Counter
def task_func(file_path, regex_pattern=r'\(.+?\)|\w+|[\W_]+'):
    """Count regex matches across all fields in a CSV file."""
    pattern = re.compile(regex_pattern)
    matches = []

    with open(file_path, mode="r", encoding="utf-8", newline="") as csv_file:
        reader = csv.reader(csv_file)
        for row in reader:
            for field in row:
                matches.extend(pattern.findall(field))

    return dict(Counter(matches))

