import random
import struct

KEYS = ['470FC614', '4A0FC614', '4B9FC614', '4C8FC614', '4D7FC614']


def task_func(hex_keys=KEYS, seed=42):
    for key in hex_keys:
        if not isinstance(key, str) or len(key) != 8:
            raise ValueError("Invalid hexadecimal string")
        try:
            int(key, 16)
        except ValueError as exc:
            raise ValueError("Invalid hexadecimal string") from exc

    selected_key = random.Random(seed).choice(hex_keys)
    floating_point_number = struct.unpack(
        ">f", bytes.fromhex(selected_key)
    )[0]

    return hashlib.md5(str(floating_point_number).encode("utf-8")).hexdigest()

