import pandas as pd
from statsmodels.tsa.stattools import adfuller


def task_func(df: pd.DataFrame, column_a: str, column_b: str, column_c: str) -> bool:
    filtered = df.loc[
        (df[column_b] > 50) & (df[column_c] == 900),
        column_a,
    ].dropna()

    if filtered.empty or filtered.nunique() <= 1:
        return True

