import socket
import select
import queue
from datetime import datetime, timedelta


def task_func(
    server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5
):
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server_socket.bind((server_address, server_port))
    server_socket.listen()
    server_socket.setblocking(False)

    sockets = [server_socket]
    output_queues = {}
    pending_data = {}

    if isinstance(run_duration, timedelta):
        duration = run_duration
    else:
        duration = timedelta(seconds=run_duration)

    start_time = datetime.now()
    end_time = start_time + duration

    def close_client(client_socket):
        if client_socket in sockets:
            sockets.remove(client_socket)
        output_queues.pop(client_socket, None)
        pending_data.pop(client_socket, None)
        try:
            client_socket.close()
        except OSError:
            pass

    try:
        while datetime.now() < end_time:
            timeout = max((end_time - datetime.now()).total_seconds(), 0)

            try:
                readable, writable, exceptional = select.select(
                    sockets,
                    [sock for sock in sockets if sock in pending_data or
                     (sock in output_queues and not output_queues[sock].empty())],
                    sockets,
                    timeout,
                )
            except (OSError, ValueError):
                break

            if server_socket in exceptional:
                break

            if server_socket in readable:
                try:
                    client_socket, _ = server_socket.accept()
                    client_socket.setblocking(False)
                    sockets.append(client_socket)
                    output_queues[client_socket] = queue.Queue()
                except (BlockingIOError, OSError):
                    pass

                readable = [sock for sock in readable if sock is not server_socket]

            for client_socket in exceptional:
                if client_socket is not server_socket:
                    close_client(client_socket)

            for client_socket in readable:
                if client_socket not in sockets:
                    continue

                try:
                    data = client_socket.recv(buffer_size)
                    if not data:
                        close_client(client_socket)
                        continue

                    response = data + str(datetime.now()).encode()
                    output_queues[client_socket].put(response)
                    pending_data.setdefault(client_socket, bytearray())
                except BlockingIOError:
                    continue
                except (ConnectionError, OSError):
                    close_client(client_socket)

            for client_socket in writable:
                if client_socket not in sockets:
                    continue

                try:
                    if not pending_data[client_socket]:
                        pending_data[client_socket].extend(
                            output_queues[client_socket].get_nowait()
                        )

                    sent = client_socket.send(pending_data[client_socket])
                    del pending_data[client_socket][:sent]

                    if not pending_data[client_socket] and output_queues[client_socket].empty():
                        pending_data.pop(client_socket, None)
                except queue.Empty:
                    pending_data.pop(client_socket, None)
                except BlockingIOError:
                    continue
                except (ConnectionError, OSError):
                    close_client(client_socket)
    finally:
        for client_socket in list(sockets):
            try:
                client_socket.close()
            except OSError:
                pass

    elapsed = datetime.now() - start_time
    return f"Echo server stopped after running for {elapsed.total_seconds():.2f} seconds."

