import pandas as pd
import numpy as np
import codecs
import re
import datetime


def task_func(start_year=1980, end_year=2000, email_domain='example.com',
              latin_names=['Sopetón', 'Méndez', 'Gómez', 'Pérez', 'Muñoz'],
              other_names=['Smith', 'Johnson', 'Williams', 'Brown', 'Jones'],
              rng_seed=None):
    if start_year > end_year:
        raise ValueError("start_year must not exceed end_year")
    if not latin_names and not other_names:
        raise ValueError("At least one name must be provided")

    rng = np.random.default_rng(rng_seed)
    names = list(latin_names) + list(other_names)

    def fix_encoding(name):
        if not isinstance(name, str):
            return str(name)
        try:
            repaired = name.encode("latin1").decode("utf-8")
            return repaired if repaired != name else name
        except (UnicodeEncodeError, UnicodeDecodeError):
            return name

    selected_names = [
        fix_encoding(name) for name in rng.choice(names, size=100)
    ]

    dates = []
    birth_years = []

    for _ in range(100):
        year = int(rng.integers(start_year, end_year + 1))
        month = int(rng.integers(1, 13))

        if year < 1:
            year_for_date = 1
        else:
            year_for_date = year

        max_day = (
            datetime.date(year_for_date, month, 1)
            .replace(day=28)
            .day
        )
        while True:
            try:
                day = int(rng.integers(1, 32))
                date_value = datetime.datetime(year_for_date, month, day)
                break
            except ValueError:
                continue

        dates.append(date_value)
        birth_years.append(year)

    emails = [
        f"{name.lower()}{year}@{email_domain}"
        for name, year in zip(selected_names, birth_years)
    ]

    return pd.DataFrame({
        "ID": np.arange(1, 101),
        "Name": selected_names,
        "Date of Birth": dates,
        "Email": emails,
    })

