import pandas as pd
import numpy as np
from statsmodels.tsa.seasonal import seasonal_decompose


def task_func(start_date='2016-01-01', periods=24, freq='M', model='additive'):
    if not isinstance(periods, (int, np.integer)) or periods <= 0:
        raise ValueError("periods must be a positive integer")

    if model not in {'additive', 'multiplicative'}:
        raise ValueError("model must be either 'additive' or 'multiplicative'")

    index = pd.date_range(start=start_date, periods=periods, freq=freq)
    frequency = str(freq).upper()

    if frequency.startswith(('M', 'MS')):
        seasonal_period = 12
    elif frequency.startswith('Q'):
        seasonal_period = 4
    elif frequency.startswith('W'):
        seasonal_period = 52
    elif frequency.startswith('D'):
        seasonal_period = 7
    elif frequency.startswith('H'):
        seasonal_period = 24
    else:
        seasonal_period = 1

    if seasonal_period > 1 and periods < 2 * seasonal_period:
        raise ValueError(
            f"at least {2 * seasonal_period} observations are required "
            f"for a seasonal period of {seasonal_period}"
        )

    rng = np.random.default_rng(42)
    trend = np.linspace(100, 200, periods)
    seasonal_pattern = np.sin(
        2 * np.pi * np.arange(periods) / seasonal_period
    )
    noise = rng.normal(0, 2, periods)

    if model == 'multiplicative':
        sales = trend * (1 + 0.1 * seasonal_pattern) * (1 + noise / 100)
    else:
        sales = trend + 10 * seasonal_pattern + noise

    sales = pd.Series(sales, index=index, name='sales')

    decomposition = seasonal_decompose(
        sales,
        model=model,
        period=seasonal_period if seasonal_period > 1 else None,
    )

    return {
        'trend': decomposition.trend,
        'seasonal': decomposition.seasonal,
        'residual': decomposition.resid,
    }

