import os
import shutil
import string

# Constants
INVALID_CHARACTERS = string.punctuation + string.whitespace


def task_func(directory_path):
    """Organize files by extension and move invalidly named files to Invalid."""
    summary = {}

    for entry in list(os.scandir(directory_path)):
        if not entry.is_file():
            continue

        filename = entry.name
        if any(character in INVALID_CHARACTERS for character in filename):
            destination_directory_name = "Invalid"
        else:
            extension = os.path.splitext(filename)[1].lstrip(".")
            destination_directory_name = extension or "No Extension"

        destination_directory = os.path.join(
            directory_path, destination_directory_name
        )
        os.makedirs(destination_directory, exist_ok=True)

        destination_path = os.path.join(destination_directory, filename)
        if os.path.abspath(entry.path) != os.path.abspath(destination_path):
            shutil.move(entry.path, destination_path)

        summary[destination_directory_name] = (
            summary.get(destination_directory_name, 0) + 1
        )

    return summary

