import pandas as pd
import folium
from geopy.geocoders import Photon


def task_func(dic):
    geolocator = Photon(user_agent="geoapiExercises")
    locations = []

    def is_coordinate(value):
        if isinstance(value, (str, bytes)) or not hasattr(value, "__len__"):
            return False
        try:
            if len(value) != 2:
                return False
            latitude, longitude = float(value[0]), float(value[1])
            return -90 <= latitude <= 90 and -180 <= longitude <= 180
        except (TypeError, ValueError):
            return False

    def resolve(value):
        if is_coordinate(value):
            return float(value[0]), float(value[1])

        if hasattr(value, "latitude") and hasattr(value, "longitude"):
            return float(value.latitude), float(value.longitude)

        if isinstance(value, str) and value.strip():
            try:
                result = geolocator.geocode(value)
                if result is not None:
                    return float(result.latitude), float(result.longitude)
            except Exception:
                return None

        return None

    if isinstance(dic, pd.DataFrame):
        records = dic.to_dict(orient="records")
    elif isinstance(dic, dict):
        if "locations" in dic and isinstance(dic["locations"], (list, tuple)):
            records = [(str(item), item) for item in dic["locations"]]
        else:
            records = list(dic.items())
    elif isinstance(dic, (list, tuple)):
        records = [(str(item), item) for item in dic]
    else:
        records = []

    for label, value in records:
        if isinstance(value, dict):
            latitude = value.get("latitude", value.get("lat"))
            longitude = value.get("longitude", value.get("lon", value.get("lng")))

            if latitude is not None and longitude is not None:
                try:
                    coordinates = (float(latitude), float(longitude))
                except (TypeError, ValueError):
                    coordinates = None
            else:
                coordinates = resolve(
                    value.get("address", value.get("location", value.get("name", label)))
                )
            marker_label = value.get("name", value.get("label", label))
        else:
            coordinates = resolve(value)
            marker_label = label

        if coordinates is not None:
            locations.append((marker_label, coordinates))

    center = (
        [
            sum(coords[0] for _, coords in locations) / len(locations),
            sum(coords[1] for _, coords in locations) / len(locations),
        ]
        if locations
        else [0, 0]
    )

    result = folium.Map(location=center, zoom_start=2)

    for label, (latitude, longitude) in locations:
        folium.Marker(
            location=[latitude, longitude],
            popup=str(label),
            tooltip=str(label),
        ).add_to(result)

    return result

