import pandas as pd
from datetime import datetime
import matplotlib.pyplot as plt
import re

# Constants
ROOMS = ["Room1", "Room2", "Room3", "Room4", "Room5"]


def task_func(date_str, booking_data):
    if not isinstance(date_str, str) or not re.fullmatch(r"\d{4}-\d{2}-\d{2}", date_str):
        raise ValueError("date_str must follow the yyyy-mm-dd format")

    try:
        requested_date = datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError as exc:
        raise ValueError("date_str must be a valid date") from exc

    if requested_date < datetime.today().date():
        raise ValueError("date_str must not refer to a past date")

    def is_booked(value):
        if isinstance(value, bool):
            return value
        if isinstance(value, str):
            return value.strip().lower() in {
                "booked", "reserved", "unavailable", "true", "yes"
            }
        if isinstance(value, (list, tuple, set)):
            return date_str in value
        return bool(value)

    statuses = []

    for room in ROOMS:
        booked = False

        if isinstance(booking_data, dict):
            date_bookings = booking_data.get(date_str)

            if isinstance(date_bookings, dict):
                booked = is_booked(date_bookings.get(room, False))
            elif isinstance(date_bookings, (list, tuple, set)):
                booked = room in date_bookings

            if not booked and room in booking_data:
                room_bookings = booking_data[room]

                if isinstance(room_bookings, dict):
                    value = room_bookings.get(date_str, False)
                    booked = is_booked(value)
                elif isinstance(room_bookings, (list, tuple, set)):
                    booked = date_str in room_bookings
                else:
                    booked = is_booked(room_bookings)

        elif isinstance(booking_data, (list, tuple)):
            for booking in booking_data:
                if isinstance(booking, dict):
                    booking_room = booking.get("room", booking.get("Room"))
                    booking_date = booking.get("date", booking.get("Date"))
                    if booking_room == room and booking_date == date_str:
                        booked = True
                        break

        statuses.append("Booked" if booked else "Available")

    report = pd.DataFrame({
        "Room": ROOMS,
        "Status": statuses,
    })

    status_values = report["Status"].map({"Available": 0, "Booked": 1})
    ax = report.plot(
        x="Room",
        y=status_values.name if status_values.name else "Status",
        kind="bar",
        legend=False,
        ylabel="Booking status",
        title=f"Room booking status for {date_str}",
    )

    ax.set_ylim(0, 1.2)
    ax.set_yticks([0, 1])
    ax.set_yticklabels(["Available", "Booked"])
    ax.set_xlabel("Room")

    return report, ax

