import random
import string

# Constants
LETTERS = string.ascii_letters
DIGITS = string.digits


def task_func(length, num_digits):
    if not isinstance(length, int) or not isinstance(num_digits, int):
        raise TypeError("length and num_digits must be integers")
    if length < 0 or num_digits < 0 or num_digits > length:
        raise ValueError("num_digits must be between 0 and length")

