import pandas as pd
from sklearn.preprocessing import LabelEncoder


def task_func(df, dct, columns=None):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("input df must be a pandas DataFrame")

    result = df.copy()
    result = result.replace(dct)

    categorical_columns = (
        list(columns)
        if columns is not None
        else result.select_dtypes(include=["object", "category"]).columns.tolist()
    )

    for column in categorical_columns:
        if column not in result.columns:
            continue
        result[column] = LabelEncoder().fit_transform(result[column])

    numerical_columns = result.select_dtypes(include="number").columns
    if len(numerical_columns) > 0:
        means = result[numerical_columns].mean()
        standard_deviations = result[numerical_columns].std()
        result[numerical_columns] = (
            result[numerical_columns] - means
        ) / standard_deviations

    return result

