import pandas as pd
from collections import Counter

def task_func(data):
    if not isinstance(data, dict):
        raise ValueError("Data must be a dictionary.")

    required_keys = {"Name", "Age"}
    score_key = "Scores" if "Scores" in data else "Score"

    if not required_keys.issubset(data) or score_key not in data:
        raise ValueError("Dictionary must contain Name, Age, and Scores keys.")

    try:
        dataframe = pd.DataFrame(data)
    except Exception as exc:
        raise ValueError("Invalid student data.") from exc

    dataframe = dataframe.sort_values(
        by=["Name", "Age"],
        ascending=[True, True],
        kind="stable",
    ).reset_index(drop=True)

    average_scores = dataframe.groupby("Name", sort=False)[score_key].mean()

    ages = dataframe["Age"].dropna().tolist()
    most_common_age = Counter(ages).most_common(1)[0][0] if ages else None

    return dataframe, average_scores, int(most_common_age) if most_common_age is not None else None

